package com.internship.controller;import com.internship.service.AIAssistantService;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/ai-assistant") @CrossOrigin(origins="*") public class AIAssistantController {private final AIAssistantService ai;public AIAssistantController(AIAssistantService a){ai=a;}@PostMapping("/chat") public ResponseEntity<Map<String,String>> chat(@RequestBody Map<String,String> req){Map<String,String> r=new HashMap<>();r.put("response",ai.chat(req.get("message")));return ResponseEntity.ok(r);}@PostMapping("/generate-certificate") public ResponseEntity<Map<String,String>> gen(@RequestParam String sn,@RequestParam String si,@RequestParam String en,@RequestParam String p,@RequestParam String sd,@RequestParam String ed){Map<String,String> r=new HashMap<>();r.put("content",ai.generateCertificateContent(sn,si,en,p,sd,ed));return ResponseEntity.ok(r);}@PostMapping("/analyze-record") public ResponseEntity<Map<String,String>> analyze(@RequestBody Map<String,String> req){Map<String,String> r=new HashMap<>();r.put("analysis",ai.analyzeDailyRecord(req.get("content")));return ResponseEntity.ok(r);}@PostMapping("/guidance") public ResponseEntity<Map<String,String>> guide(@RequestBody Map<String,String> req){Map<String,String> r=new HashMap<>();r.put("guidance",ai.getInternshipGuidance(req.get("question")));return ResponseEntity.ok(r);}}
